/* ── tween + play loop ──────────────────────────────────────────────────── */
let tween = null, playing = false, playPhase = 0, lastT = performance.now();
function tweenTo(target, dur) { tween = { from: progT, to: target, t0: performance.now(), dur: dur || 800 }; }
function stopPlay() { if (playing) { playing = false; btnPlay.textContent = '▶ Play mechanism'; btnPlay.classList.remove('active'); } }
btnPlay.addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true; tween = null; playPhase = progT;
  btnPlay.textContent = '❚❚ Pause';
  btnPlay.classList.add('active');
