  const X = new THREE.Vector3(dcx, 0, 0);
  const NU = new THREE.Vector3(-dcn, 0, 0);
  const qNu = -(1 - 0.4 * t), qX = -(0.6 + 0.4 * t);
  const field = [
    { p: NU, r: 1.9, q: qNu },
    { p: ORIGIN.clone(), r: 1.4, q: 0.20 },
    { p: X, r: 1.9, q: qX },
    { p: H[0], r: 1.1, q: 0.08 },
    { p: H[1], r: 1.1, q: 0.08 },
    { p: H[2], r: 1.1, q: 0.08 }
  ];
  for (const a of field) { a.r2 = a.r * a.r; a.cut = a.r2 * 9; }
  return { t, H, X, NU, field };
