    const dx = x - a.p.x, dy = y - a.p.y, dz = z - a.p.z;
    let dd = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (dd < 0.8) dd = 0.8;
    v += a.q * Math.exp(-dd / 2.2) / dd;
  }
  return v;
}

const RAMP = [
  [0.00, new THREE.Color(0xD9534F)],
  [0.18, new THREE.Color(0xE8746B)],
  [0.38, new THREE.Color(0xE8945A)],
  [0.55, new THREE.Color(0xE8E06A)],
  [0.72, new THREE.Color(0x8FD18F)],
  [1.00, new THREE.Color(0x7F9FE0)]
];
const _rc = new THREE.Color();
function rampColor(u) {
  if (u <= 0) return RAMP[0][1];
  if (u >= 1) return RAMP[RAMP.length - 1][1];
  for (let i = 1; i < RAMP.length; i++) {
    if (u <= RAMP[i][0]) {
      const f = (u - RAMP[i - 1][0]) / (RAMP[i][0] - RAMP[i - 1][0]);
      return _rc.copy(RAMP[i - 1][1]).lerp(RAMP[i][1], f);
    }
  }
  return RAMP[RAMP.length - 1][1];
}

/* ── surface-nets metaball mesh ─────────────────────────────────────────── */
const NX = 56, NY = 26, NZ = 26;
const GX0 = -6.9, GX1 = 6.9, GY0 = -2.95, GY1 = 2.95, GZ0 = -2.95, GZ1 = 2.95;
const HXs = (GX1 - GX0) / (NX - 1), HYs = (GY1 - GY0) / (NY - 1), HZs = (GZ1 - GZ0) / (NZ - 1);
const FGRID = new Float32Array(NX * NY * NZ);
const CIDX = new Int32Array((NX - 1) * (NY - 1) * (NZ - 1));

const EDG = [];
for (let c = 0; c < 8; c++) {
  if (!(c & 1)) EDG.push([c, c | 1]);
  if (!(c & 2)) EDG.push([c, c | 2]);
  if (!(c & 4)) EDG.push([c, c | 4]);
}

const blobMat = new THREE.MeshPhysicalMaterial({
  vertexColors: true, transparent: true, opacity: 0.55,
  roughness: 0.35, metalness: 0.0, clearcoat: 0.55, clearcoatRoughness: 0.35,
  side: THREE.DoubleSide, depthWrite: false
});
const blobMesh = new THREE.Mesh(new THREE.BufferGeometry(), blobMat);
blobMesh.renderOrder = 2;
scene.add(blobMesh);

function cellId(i, j, k) { return CIDX[i + (NX - 1) * (j + (NY - 1) * k)]; }

function rebuildSurface(A) {
  const Af = A.field;
  const nxy = NX * NY;
  let n = 0;
  for (let k = 0; k < NZ; k++) {
    const z = GZ0 + k * HZs;
    for (let j = 0; j < NY; j++) {
      const y = GY0 + j * HYs;
      for (let i = 0; i < NX; i++, n++) FGRID[n] = fieldVal(GX0 + i * HXs, y, z, Af);
    }
  }
  CIDX.fill(-1);
  const P = [], NR = [], CO = [], IX = [];
  const vv = new Array(8);
  let vc = 0;
  for (let k = 0; k < NZ - 1; k++) for (let j = 0; j < NY - 1; j++) for (let i = 0; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    vv[0] = FGRID[b0]; vv[1] = FGRID[b0 + 1]; vv[2] = FGRID[b0 + NX]; vv[3] = FGRID[b0 + NX + 1];
    vv[4] = FGRID[b0 + nxy]; vv[5] = FGRID[b0 + nxy + 1]; vv[6] = FGRID[b0 + nxy + NX]; vv[7] = FGRID[b0 + nxy + NX + 1];
    let mask = 0;
    for (let c = 0; c < 8; c++) if (vv[c] > ISO) mask |= 1 << c;
    if (mask === 0 || mask === 255) continue;
    let sx = 0, sy = 0, sz = 0, cnt = 0;
    for (let e = 0; e < 12; e++) {
      const a = EDG[e][0], b = EDG[e][1];
      const va = vv[a], vb = vv[b];
      if ((va > ISO) === (vb > ISO)) continue;
      let s = (ISO - va) / (vb - va);
      if (!(s >= 0 && s <= 1)) s = 0.5;
      const ax = a & 1, ay = (a >> 1) & 1, az = (a >> 2) & 1;
      const bx = b & 1, by = (b >> 1) & 1, bz = (b >> 2) & 1;
      sx += ax + (bx - ax) * s; sy += ay + (by - ay) * s; sz += az + (bz - az) * s;
      cnt++;
    }
    if (!cnt) continue;
    const px = GX0 + (i + sx / cnt) * HXs;
    const py = GY0 + (j + sy / cnt) * HYs;
    const pz = GZ0 + (k + sz / cnt) * HZs;
    CIDX[i + (NX - 1) * (j + (NY - 1) * k)] = vc++;
    P.push(px, py, pz);
    const h = 0.13;
    let gx = fieldVal(px + h, py, pz, Af) - fieldVal(px - h, py, pz, Af);
    let gy = fieldVal(px, py + h, pz, Af) - fieldVal(px, py - h, pz, Af);
    let gz = fieldVal(px, py, pz + h, Af) - fieldVal(px, py, pz - h, Af);
    let L = Math.sqrt(gx * gx + gy * gy + gz * gz) || 1;
    NR.push(-gx / L, -gy / L, -gz / L);
    const col = rampColor((potVal(px, py, pz, Af) - VMIN) / (VMAX - VMIN));
    CO.push(col.r, col.g, col.b);
  }

  function tri(i0, i1, i2) {
    const ax = P[3 * i0], ay = P[3 * i0 + 1], az = P[3 * i0 + 2];
    const ux = P[3 * i1] - ax, uy = P[3 * i1 + 1] - ay, uz = P[3 * i1 + 2] - az;
    const wx = P[3 * i2] - ax, wy = P[3 * i2 + 1] - ay, wz = P[3 * i2 + 2] - az;
    const cx = uy * wz - uz * wy, cy = uz * wx - ux * wz, cz = ux * wy - uy * wx;
    const dp = cx * NR[3 * i0] + cy * NR[3 * i0 + 1] + cz * NR[3 * i0 + 2];
    if (dp >= 0) IX.push(i0, i1, i2); else IX.push(i0, i2, i1);
  }
  function quad(a, b, c, dd) {
    if (a < 0 || b < 0 || c < 0 || dd < 0) return;
    tri(a, b, c); tri(a, c, dd);
  }

  for (let k = 1; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 0; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + 1] > ISO)) continue;
    quad(cellId(i, j - 1, k - 1), cellId(i, j, k - 1), cellId(i, j, k), cellId(i, j - 1, k));
  }
  for (let k = 1; k < NZ - 1; k++) for (let j = 0; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + NX] > ISO)) continue;
    quad(cellId(i - 1, j, k - 1), cellId(i, j, k - 1), cellId(i, j, k), cellId(i - 1, j, k));
  }
  for (let k = 0; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + nxy] > ISO)) continue;
    quad(cellId(i - 1, j - 1, k), cellId(i, j - 1, k), cellId(i, j, k), cellId(i - 1, j - 1, k));
  }

  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(NR, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(CO, 3));
  g.setIndex(IX);
  g.computeBoundingSphere();
  const old = blobMesh.geometry;
  blobMesh.geometry = g;
  if (old) old.dispose();
}

/* ── ball-and-stick model ───────────────────────────────────────────────── */
const bsGroup = new THREE.Group();
scene.add(bsGroup);

const matC = new THREE.MeshStandardMaterial({ color: 0x60706a, roughness: 0.45, metalness: 0.05 });
const matH = new THREE.MeshStandardMaterial({ color: 0xdde2de, roughness: 0.5 });
const matHal = new THREE.MeshStandardMaterial({ color: 0xa0301c, roughness: 0.4 });
const matBond = new THREE.MeshStandardMaterial({ color: 0xb9c0bb, roughness: 0.6 });
const matBX = new THREE.MeshStandardMaterial({ color: 0xa8aeaa, roughness: 0.6, transparent: true, opacity: 1 });
const matBN = new THREE.MeshStandardMaterial({ color: 0xa8aeaa, roughness: 0.6, transparent: true, opacity: 1 });
const matDotX = new THREE.MeshStandardMaterial({ color: 0x8b9490, roughness: 0.6, transparent: true, opacity: 0.95 });
const matDotN = new THREE.MeshStandardMaterial({ color: 0x8b9490, roughness: 0.6, transparent: true, opacity: 0.95 });

const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 16);
const cMesh = new THREE.Mesh(new THREE.SphereGeometry(0.45, 32, 24), matC);
const xMesh = new THREE.Mesh(new THREE.SphereGeometry(0.62, 32, 24), matHal);
const nuMesh = new THREE.Mesh(new THREE.SphereGeometry(0.62, 32, 24), matHal);
bsGroup.add(cMesh, xMesh, nuMesh);

const hMesh = [], hBond = [];
for (let k = 0; k < 3; k++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.28, 24, 18), matH);
  const b = new THREE.Mesh(cylGeo, matBond);
  hMesh.push(s); hBond.push(b); bsGroup.add(s, b);
}
const cxBond = new THREE.Mesh(cylGeo, matBX);
const cnBond = new THREE.Mesh(cylGeo, matBN);
bsGroup.add(cxBond, cnBond);

const dotGeo = new THREE.SphereGeometry(0.075, 12, 10);
const cxDots = [], cnDots = [];
for (let i = 0; i < 8; i++) {
  const a = new THREE.Mesh(dotGeo, matDotX); cxDots.push(a); bsGroup.add(a);
  const b = new THREE.Mesh(dotGeo, matDotN); cnDots.push(b); bsGroup.add(b);
}

const _up = new THREE.Vector3(0, 1, 0), _dir = new THREE.Vector3(), _mid = new THREE.Vector3();
function setBond(mesh, a, b, rad) {
  _dir.subVectors(b, a);
  const len = _dir.length() || 1e-4;
  _mid.addVectors(a, b).multiplyScalar(0.5);
  mesh.position.copy(_mid);
  mesh.quaternion.setFromUnitVectors(_up, _dir.normalize());
  mesh.scale.set(rad, len, rad);
}

let showBS = true;

function updPartial(cyl, dots, mat, dotMat, a, b, order) {
  const solid = THREE.MathUtils.smoothstep(order, 0.60, 0.95);
  mat.opacity = solid;
  mat.transparent = solid < 0.995;
  cyl.visible = showBS && solid > 0.03;
  setBond(cyl, a, b, 0.11);
  const dotOn = showBS && order > 0.08 && solid < 0.97;
  dotMat.opacity = 0.35 + 0.6 * Math.min(1, order * 1.6);
  for (let i = 0; i < dots.length; i++) {
    dots[i].visible = dotOn;
    if (dotOn) dots[i].position.lerpVectors(a, b, (i + 1) / (dots.length + 1));
  }
}

function updateBallStick(A) {
  bsGroup.visible = showBS;
  cMesh.position.copy(ORIGIN);
  for (let k = 0; k < 3; k++) {
    hMesh[k].position.copy(A.H[k]);
    setBond(hBond[k], ORIGIN, A.H[k], 0.085);
  }
  xMesh.position.copy(A.X);
  nuMesh.position.copy(A.NU);
  updPartial(cxBond, cxDots, matBX, matDotX, ORIGIN, A.X, 1 - A.t);
  updPartial(cnBond, cnDots, matBN, matDotN, ORIGIN, A.NU, A.t);
}

registerInteractive(cMesh, {
  title: 'The sp³ → sp² → sp³ carbon',
  tooltip: 'Central carbon — it inverts',
  body: 'The electrophilic carbon. As Nu attacks from the backside the carbon rehybridises to sp² at the transition state (three coplanar C–H bonds), then re-pyramidalises on the opposite side — an inversion of configuration, like an umbrella turning inside out.'
});
registerInteractive(xMesh, {
  title: 'Leaving group X',
  tooltip: 'Leaving group X',
  body: 'The C–X bond stretches from 1.8 Å to 4.0 Å across the reaction. Electron density (red on the map) flows onto X until it departs as X:⁻.'
});
registerInteractive(nuMesh, {
