// @FIGURE_CODE_BEGIN
// ── element spec ────────────────────────────────────────────────────────────
// central carbon        → SphereGeometry(0.42)  MeshStandard  #63736c
// 3 × hydrogen          → SphereGeometry(0.27)  MeshStandard  #dfe4e0
// 3 × C–H bond          → CylinderGeometry(r=0.075)           #bcc3be
// halide X              → SphereGeometry(0.60)  MeshStandard  #9c2d1a
// nucleophile Nu        → SphereGeometry(0.60)  MeshStandard  #9c2d1a
// C–X / C–Nu bonds      → CylinderGeometry(r=0.10) faded by bond order
//                         + 8 dot spheres (r=0.07) for the partial bonds
// ESP surface           → surface-nets metaball mesh, Laplacian-smoothed and
//                         re-projected on the isosurface, per-vertex rainbow
//                         colours, MeshPhysicalMaterial transparent
// compare mode          → three static stacked stages (t = 0, 0.5, 1)
// captions / atom tags  → addLabel ("Tetrahedral"/"Planar", Nu, C, X)
// 2D reaction scheme    → SVG in #ui, active row highlighted
// ────────────────────────────────────────────────────────────────────────────

const ORIGIN = new THREE.Vector3(0, 0, 0);

/* ── lighting ───────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xf0f0f0, 1.15));
const dlA = new THREE.DirectionalLight(0xffffff, 0.55); dlA.position.set(3, 6, 10); scene.add(dlA);
const dlB = new THREE.DirectionalLight(0xffffff, 0.30); dlB.position.set(-7, -3, -6); scene.add(dlB);

/* ── molecular state ────────────────────────────────────────────────────── */
function atomState(t) {
  const dcx = 1.8 + 2.2 * Math.pow(t, 1.7);            // 1.8 → ~2.5 → 4.0
  const dcn = 1.5 + 2.7 * Math.pow(1 - t, 1.7);        // 4.2 → ~2.3 → 1.5
  const th = THREE.MathUtils.degToRad(109.5 - 39 * t); // H–C–X angle
  const H = [];
  for (let k = 0; k < 3; k++) {
    const ph = THREE.MathUtils.degToRad(270 + 120 * k);
    H.push(new THREE.Vector3(
      Math.cos(th),
      Math.sin(th) * Math.sin(ph),
      Math.sin(th) * Math.cos(ph)
    ).multiplyScalar(1.09));
  }
  const X = new THREE.Vector3(dcx, 0, 0);
  const NU = new THREE.Vector3(-dcn, 0, 0);
  const field = [
    { p: NU, r: 1.95, rw: 2.2, s: -1.00 + 0.40 * t },
    { p: ORIGIN.clone(), r: 1.55, rw: 1.8, s: 0.15 },
    { p: X, r: 1.95, rw: 2.2, s: -0.62 - 0.38 * t },
    { p: H[0], r: 1.15, rw: 1.4, s: 0.50 },
    { p: H[1], r: 1.15, rw: 1.4, s: 0.50 },
    { p: H[2], r: 1.15, rw: 1.4, s: 0.50 }
  ];
  for (const a of field) { a.r2 = a.r * a.r; a.cut = a.r2 * 9; a.gw = 1 / (2 * a.rw * a.rw); }
  return { t, H, X, NU, field };
}

/* ── implicit field + electrostatic potential ───────────────────────────── */
const ISO = 1.0, VMIN = -1.0, VMAX = 0.55;

function fieldVal(x, y, z, A) {
  let s = 0;
  for (let n = 0; n < A.length; n++) {
    const a = A[n];
    const dx = x - a.p.x, dy = y - a.p.y, dz = z - a.p.z;
    const d2 = dx * dx + dy * dy + dz * dz;
    if (d2 < 1e-6) return 99;
    if (d2 > a.cut) continue;
    const q = a.r2 / d2;
    s += q * q * q;
  }
  return s;
}

// Locally blended surface potential: each atom paints its own neighbourhood,
// so the halide/nucleophile lobes stay saturated red and the C–H side is blue.
function potVal(x, y, z, A) {
  let num = 0, den = 1e-9;
  for (let n = 0; n < A.length; n++) {
    const a = A[n];
    const dx = x - a.p.x, dy = y - a.p.y, dz = z - a.p.z;
    const w = Math.exp(-(dx * dx + dy * dy + dz * dz) * a.gw);
    num += w * a.s; den += w;
  }
  return num / den;
}

const RAMP = [
  [0.00, new THREE.Color(0xe02020)],
  [0.12, new THREE.Color(0xf04530)],
  [0.28, new THREE.Color(0xff8c2a)],
  [0.44, new THREE.Color(0xffe23a)],
  [0.60, new THREE.Color(0x5ad155)],
  [0.78, new THREE.Color(0x33c6d6)],
  [1.00, new THREE.Color(0x3a5fd9)]
];
const _rc = new THREE.Color();
function rampColor(u) {
  if (u <= 0) return RAMP[0][1];
  if (u >= 1) return RAMP[RAMP.length - 1][1];
  for (let i = 1; i < RAMP.length; i++) {
    if (u <= RAMP[i][0]) {
      const f = (u - RAMP[i - 1][0]) / (RAMP[i][0] - RAMP[i - 1][0]);
      return _rc.copy(RAMP[i - 1][1]).lerp(RAMP[i][1], f);
    }
  }
  return RAMP[RAMP.length - 1][1];
}

/* ── smoothed surface-nets metaball builder ─────────────────────────────── */
const NX = 76, NY = 32, NZ = 32;
const GX0 = -6.7, GX1 = 6.7, GY0 = -2.55, GY1 = 2.55, GZ0 = -2.55, GZ1 = 2.55;
const HXs = (GX1 - GX0) / (NX - 1), HYs = (GY1 - GY0) / (NY - 1), HZs = (GZ1 - GZ0) / (NZ - 1);
const FGRID = new Float32Array(NX * NY * NZ);
const CIDX = new Int32Array((NX - 1) * (NY - 1) * (NZ - 1));

const EDG = [];
for (let c = 0; c < 8; c++) {
  if (!(c & 1)) EDG.push([c, c | 1]);
  if (!(c & 2)) EDG.push([c, c | 2]);
  if (!(c & 4)) EDG.push([c, c | 4]);
}

function cellId(i, j, k) { return CIDX[i + (NX - 1) * (j + (NY - 1) * k)]; }

function buildSurfaceGeometry(A) {
  const Af = A.field, nxy = NX * NY;
  let n = 0;
  for (let k = 0; k < NZ; k++) {
    const z = GZ0 + k * HZs;
    for (let j = 0; j < NY; j++) {
      const y = GY0 + j * HYs;
      for (let i = 0; i < NX; i++, n++) FGRID[n] = fieldVal(GX0 + i * HXs, y, z, Af);
    }
  }
  CIDX.fill(-1);

  const PX = [], PY = [], PZ = [];
  const vv = new Array(8);
  let vc = 0;
  for (let k = 0; k < NZ - 1; k++) for (let j = 0; j < NY - 1; j++) for (let i = 0; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    vv[0] = FGRID[b0]; vv[1] = FGRID[b0 + 1]; vv[2] = FGRID[b0 + NX]; vv[3] = FGRID[b0 + NX + 1];
    vv[4] = FGRID[b0 + nxy]; vv[5] = FGRID[b0 + nxy + 1]; vv[6] = FGRID[b0 + nxy + NX]; vv[7] = FGRID[b0 + nxy + NX + 1];
    let mask = 0;
    for (let c = 0; c < 8; c++) if (vv[c] > ISO) mask |= 1 << c;
    if (mask === 0 || mask === 255) continue;
    let sx = 0, sy = 0, sz = 0, cnt = 0;
    for (let e = 0; e < 12; e++) {
      const a = EDG[e][0], b = EDG[e][1];
      const va = vv[a], vb = vv[b];
      if ((va > ISO) === (vb > ISO)) continue;
      let s = (ISO - va) / (vb - va);
      if (!(s >= 0 && s <= 1)) s = 0.5;
      const ax = a & 1, ay = (a >> 1) & 1, az = (a >> 2) & 1;
      const bx = b & 1, by = (b >> 1) & 1, bz = (b >> 2) & 1;
      sx += ax + (bx - ax) * s; sy += ay + (by - ay) * s; sz += az + (bz - az) * s;
      cnt++;
    }
    if (!cnt) continue;
    CIDX[i + (NX - 1) * (j + (NY - 1) * k)] = vc++;
    PX.push(GX0 + (i + sx / cnt) * HXs);
    PY.push(GY0 + (j + sy / cnt) * HYs);
    PZ.push(GZ0 + (k + sz / cnt) * HZs);
  }

  // quads (surface nets dual faces)
  const Q = [];
  function quad(a, b, c, dd) { if (a >= 0 && b >= 0 && c >= 0 && dd >= 0) Q.push(a, b, c, dd); }
  for (let k = 1; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 0; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + 1] > ISO)) continue;
    quad(cellId(i, j - 1, k - 1), cellId(i, j, k - 1), cellId(i, j, k), cellId(i, j - 1, k));
  }
  for (let k = 1; k < NZ - 1; k++) for (let j = 0; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + NX] > ISO)) continue;
    quad(cellId(i - 1, j, k - 1), cellId(i, j, k - 1), cellId(i, j, k), cellId(i - 1, j, k));
  }
  for (let k = 0; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const b0 = i + NX * j + nxy * k;
    if ((FGRID[b0] > ISO) === (FGRID[b0 + nxy] > ISO)) continue;
    quad(cellId(i - 1, j - 1, k), cellId(i, j - 1, k), cellId(i, j, k), cellId(i - 1, j, k));
  }

  // adjacency for Laplacian smoothing
  const adjS = new Int32Array(vc + 1);
  for (let q = 0; q < Q.length; q += 4) {
    for (let e = 0; e < 4; e++) { adjS[Q[q + e]] += 2; }
  }
  const start = new Int32Array(vc + 1);
  let acc = 0;
  for (let v = 0; v < vc; v++) { start[v] = acc; acc += adjS[v]; }
  start[vc] = acc;
  const fill = new Int32Array(vc);
  const adj = new Int32Array(acc);
  for (let q = 0; q < Q.length; q += 4) {
    for (let e = 0; e < 4; e++) {
      const a = Q[q + e], b = Q[q + ((e + 1) % 4)];
      adj[start[a] + fill[a]++] = b;
      adj[start[b] + fill[b]++] = a;
    }
  }

  const px = Float32Array.from(PX), py = Float32Array.from(PY), pz = Float32Array.from(PZ);
  const tx = new Float32Array(vc), ty = new Float32Array(vc), tz = new Float32Array(vc);
  const h = 0.11, lam = 0.62;
  for (let it = 0; it < 3; it++) {
    for (let v = 0; v < vc; v++) {
      const s0 = start[v], s1 = s0 + fill[v];
      if (s1 <= s0) { tx[v] = px[v]; ty[v] = py[v]; tz[v] = pz[v]; continue; }
      let ax = 0, ay = 0, az = 0;
      for (let m = s0; m < s1; m++) { const w = adj[m]; ax += px[w]; ay += py[w]; az += pz[w]; }
      const inv = 1 / (s1 - s0);
      tx[v] = px[v] + lam * (ax * inv - px[v]);
      ty[v] = py[v] + lam * (ay * inv - py[v]);
      tz[v] = pz[v] + lam * (az * inv - pz[v]);
    }
    // re-project onto the isosurface so smoothing does not shrink the blob
    for (let v = 0; v < vc; v++) {
      const x = tx[v], y = ty[v], z = tz[v];
      const f = fieldVal(x, y, z, Af);
      const gx = (fieldVal(x + h, y, z, Af) - fieldVal(x - h, y, z, Af)) / (2 * h);
      const gy = (fieldVal(x, y + h, z, Af) - fieldVal(x, y - h, z, Af)) / (2 * h);
      const gz = (fieldVal(x, y, z + h, Af) - fieldVal(x, y, z - h, Af)) / (2 * h);
      const g2 = gx * gx + gy * gy + gz * gz;
      let dx = 0, dy = 0, dz = 0;
      if (g2 > 1e-8) {
        const c = -(f - ISO) / g2;
        dx = c * gx; dy = c * gy; dz = c * gz;
        const L = Math.sqrt(dx * dx + dy * dy + dz * dz);
        if (L > 0.30) { const s = 0.30 / L; dx *= s; dy *= s; dz *= s; }
      }
      px[v] = x + dx; py[v] = y + dy; pz[v] = z + dz;
    }
  }

  const POS = new Float32Array(vc * 3), NRM = new Float32Array(vc * 3), COL = new Float32Array(vc * 3);
  for (let v = 0; v < vc; v++) {
    const x = px[v], y = py[v], z = pz[v];
    POS[3 * v] = x; POS[3 * v + 1] = y; POS[3 * v + 2] = z;
    const gx = fieldVal(x + h, y, z, Af) - fieldVal(x - h, y, z, Af);
    const gy = fieldVal(x, y + h, z, Af) - fieldVal(x, y - h, z, Af);
    const gz = fieldVal(x, y, z + h, Af) - fieldVal(x, y, z - h, Af);
    const L = Math.sqrt(gx * gx + gy * gy + gz * gz) || 1;
    NRM[3 * v] = -gx / L; NRM[3 * v + 1] = -gy / L; NRM[3 * v + 2] = -gz / L;
    const col = rampColor((potVal(x, y, z, Af) - VMIN) / (VMAX - VMIN));
    COL[3 * v] = col.r; COL[3 * v + 1] = col.g; COL[3 * v + 2] = col.b;
  }

  const IX = [];
  function tri(i0, i1, i2) {
    const ax = POS[3 * i0], ay = POS[3 * i0 + 1], az = POS[3 * i0 + 2];
    const ux = POS[3 * i1] - ax, uy = POS[3 * i1 + 1] - ay, uz = POS[3 * i1 + 2] - az;
    const wx = POS[3 * i2] - ax, wy = POS[3 * i2 + 1] - ay, wz = POS[3 * i2 + 2] - az;
    const cx = uy * wz - uz * wy, cy = uz * wx - ux * wz, cz = ux * wy - uy * wx;
    const dp = cx * NRM[3 * i0] + cy * NRM[3 * i0 + 1] + cz * NRM[3 * i0 + 2];
