    tri(Q[q], Q[q + 1], Q[q + 2]);
    tri(Q[q], Q[q + 2], Q[q + 3]);
  }

  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(POS, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(NRM, 3));
  g.setAttribute('color', new THREE.BufferAttribute(COL, 3));
  g.setIndex(IX);
  g.computeBoundingSphere();
  g.computeBoundingBox();
  return g;
}

const blobMat = new THREE.MeshPhysicalMaterial({
  vertexColors: true, transparent: true, opacity: 0.60,
  roughness: 0.30, metalness: 0.0, clearcoat: 0.8, clearcoatRoughness: 0.25,
  side: THREE.DoubleSide, depthWrite: false
});
const blobMesh = new THREE.Mesh(new THREE.BufferGeometry(), blobMat);
blobMesh.renderOrder = 2;
scene.add(blobMesh);

registerInteractive(blobMesh, {
  title: 'Electrostatic potential map',
  tooltip: 'Electrostatic potential surface',
  body: 'Colour shows the electrostatic potential on an electron-density surface: red = most negative (electron rich), through orange-yellow-green, to blue = most positive. Watch the red charge migrate from the nucleophile, through both ends of the transition state, onto the departing leaving group.'
});

/* ── ball-and-stick ─────────────────────────────────────────────────────── */
const matC = new THREE.MeshStandardMaterial({ color: 0x63736c, roughness: 0.45, metalness: 0.05 });
const matH = new THREE.MeshStandardMaterial({ color: 0xdfe4e0, roughness: 0.5 });
const matHal = new THREE.MeshStandardMaterial({ color: 0x9c2d1a, roughness: 0.4 });
const matBond = new THREE.MeshStandardMaterial({ color: 0xbcc3be, roughness: 0.6 });
const matBX = new THREE.MeshStandardMaterial({ color: 0xa8aeaa, roughness: 0.6, transparent: true, opacity: 1 });
const matBN = new THREE.MeshStandardMaterial({ color: 0xa8aeaa, roughness: 0.6, transparent: true, opacity: 1 });
const matDotX = new THREE.MeshStandardMaterial({ color: 0x8b9490, roughness: 0.6, transparent: true, opacity: 0.95 });
const matDotN = new THREE.MeshStandardMaterial({ color: 0x8b9490, roughness: 0.6, transparent: true, opacity: 0.95 });

const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 16);
const geoC = new THREE.SphereGeometry(0.42, 32, 24);
const geoH = new THREE.SphereGeometry(0.27, 24, 18);
const geoHal = new THREE.SphereGeometry(0.60, 32, 24);
const dotGeo = new THREE.SphereGeometry(0.07, 12, 10);

const _up = new THREE.Vector3(0, 1, 0), _dir = new THREE.Vector3(), _mid = new THREE.Vector3();
function setBond(mesh, a, b, rad) {
  _dir.subVectors(b, a);
  const len = _dir.length() || 1e-4;
  _mid.addVectors(a, b).multiplyScalar(0.5);
  mesh.position.copy(_mid);
  mesh.quaternion.setFromUnitVectors(_up, _dir.normalize());
  mesh.scale.set(rad, len, rad);
}

const bsGroup = new THREE.Group();
scene.add(bsGroup);
const cMesh = new THREE.Mesh(geoC, matC);
const xMesh = new THREE.Mesh(geoHal, matHal);
const nuMesh = new THREE.Mesh(geoHal, matHal);
bsGroup.add(cMesh, xMesh, nuMesh);
const hMesh = [], hBond = [];
for (let k = 0; k < 3; k++) {
  const s = new THREE.Mesh(geoH, matH);
  const b = new THREE.Mesh(cylGeo, matBond);
  hMesh.push(s); hBond.push(b); bsGroup.add(s, b);
}
const cxBond = new THREE.Mesh(cylGeo, matBX);
const cnBond = new THREE.Mesh(cylGeo, matBN);
bsGroup.add(cxBond, cnBond);
const cxDots = [], cnDots = [];
for (let i = 0; i < 8; i++) {
  const a = new THREE.Mesh(dotGeo, matDotX); cxDots.push(a); bsGroup.add(a);
  const b = new THREE.Mesh(dotGeo, matDotN); cnDots.push(b); bsGroup.add(b);
