  cyl.visible = showBS && solid > 0.03;
  setBond(cyl, a, b, 0.10);
  const dotOn = showBS && order > 0.08 && solid < 0.97;
  dotMat.opacity = 0.35 + 0.6 * Math.min(1, order * 1.6);
  for (let i = 0; i < dots.length; i++) {
    dots[i].visible = dotOn;
    if (dotOn) dots[i].position.lerpVectors(a, b, (i + 1) / (dots.length + 1));
  }
}

function updateBallStick(A) {
  bsGroup.visible = showBS;
  cMesh.position.copy(ORIGIN);
  for (let k = 0; k < 3; k++) {
    hMesh[k].position.copy(A.H[k]);
    setBond(hBond[k], ORIGIN, A.H[k], 0.075);
  }
  xMesh.position.copy(A.X);
  nuMesh.position.copy(A.NU);
  updPartial(cxBond, cxDots, matBX, matDotX, ORIGIN, A.X, 1 - A.t);
  updPartial(cnBond, cnDots, matBN, matDotN, ORIGIN, A.NU, A.t);
}

registerInteractive(cMesh, {
  title: 'The sp³ → sp² → sp³ carbon',
  tooltip: 'Central carbon — it inverts',
  body: 'The electrophilic carbon. As Nu attacks from the backside the carbon rehybridises to sp² at the transition state (three coplanar C–H bonds), then re-pyramidalises on the opposite side — an inversion of configuration, like an umbrella turning inside out.'
});
registerInteractive(xMesh, {
  title: 'Leaving group X',
  tooltip: 'Leaving group X',
  body: 'The C–X bond stretches from 1.8 Å to 4.0 Å across the reaction. Electron density (red on the map) flows onto X until it departs as X:⁻.'
});
registerInteractive(nuMesh, {
  title: 'Nucleophile Nu:⁻',
  tooltip: 'Nucleophile Nu:⁻',
  body: 'Nu attacks along the line exactly 180° opposite the C–X bond — backside attack. Only that direction overlaps the empty σ* orbital of C–X, which is why S_N2 always inverts configuration.'
});

/* ── static stage builder (compare mode) ────────────────────────────────── */
function addStaticBond(g, a, b, order) {
  if (order > 0.9) {
    const m = new THREE.Mesh(cylGeo, matBond);
    setBond(m, a, b, 0.10); g.add(m);
  } else if (order > 0.05) {
    for (let i = 1; i <= 8; i++) {
      const s = new THREE.Mesh(dotGeo, matDotX);
      s.position.lerpVectors(a, b, i / 9); g.add(s);
    }
  }
}
function makeBallStickGroup(A) {
  const g = new THREE.Group();
  const c = new THREE.Mesh(geoC, matC); g.add(c);
  for (let k = 0; k < 3; k++) {
    const s = new THREE.Mesh(geoH, matH); s.position.copy(A.H[k]); g.add(s);
    const b = new THREE.Mesh(cylGeo, matBond); setBond(b, ORIGIN, A.H[k], 0.075); g.add(b);
  }
  const x = new THREE.Mesh(geoHal, matHal); x.position.copy(A.X); g.add(x);
  const nu = new THREE.Mesh(geoHal, matHal); nu.position.copy(A.NU); g.add(nu);
  addStaticBond(g, ORIGIN, A.X, 1 - A.t);
  addStaticBond(g, ORIGIN, A.NU, A.t);
  return g;
}

/* ── initial build + camera ─────────────────────────────────────────────── */
let progT = 0;
blobMesh.geometry.dispose();
blobMesh.geometry = buildSurfaceGeometry(atomState(0));
updateBallStick(atomState(0));
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 10, heightFraction: 0.88 });

/* ── labels ─────────────────────────────────────────────────────────────── */
const MAG = '#d81b8c';
const capLabel = addLabel('<b>Tetrahedral</b>', new THREE.Vector3(0, -2.95, 0), { fontSize: '21px' });
const nuLabel = addLabel('Nu:<sup>−</sup>', new THREE.Vector3(-4.2, 2.3, 0), { fontSize: '17px', color: MAG, bold: true });
const xLabel = addLabel('X', new THREE.Vector3(1.8, 2.3, 0), { fontSize: '17px', color: MAG, bold: true });
const cLabel = addLabel('C', new THREE.Vector3(0, 0.55, 0), { fontSize: '16px', color: '#1a1a1a', bold: true, offset: [-20, -10] });
const mainLabels = [capLabel, nuLabel, xLabel, cLabel];

function updateLabels(A) {
  nuLabel.pos.copy(A.NU); nuLabel.pos.y += 2.25;
  xLabel.pos.copy(A.X); xLabel.pos.y += 2.25;
  cLabel.pos.set(0, 0.55, 0);
  const t = A.t;
  nuLabel.div.innerHTML = t < 0.08 ? 'Nu:<sup>−</sup>' : (t > 0.94 ? 'Nu' : 'Nu<sup>δ−</sup>');
  xLabel.div.innerHTML = t > 0.94 ? 'X:<sup>−</sup>' : (t < 0.08 ? 'X' : 'X<sup>δ−</sup>');
  let cap;
  if (t < 0.25) cap = '<b>Tetrahedral</b>';
  else if (t < 0.42) cap = 'flattening…';
  else if (t <= 0.58) cap = '<b>Planar</b>';
  else if (t < 0.75) cap = 'inverting…';
  else cap = '<b>Tetrahedral</b> (inverted)';
  capLabel.div.innerHTML = cap;
}

/* ── compare-all-stages group ───────────────────────────────────────────── */
let compareGroup = null;
const compareLabels = [];
const blobMatStatic = blobMat.clone();
blobMatStatic.opacity = 0.70;

function buildCompare() {
  compareGroup = new THREE.Group();
  const ys = [5.4, 0, -5.4], ts = [0, 0.5, 1], caps = ['Tetrahedral', 'Planar', 'Tetrahedral'];
  for (let i = 0; i < 3; i++) {
    const A = atomState(ts[i]);
    const row = new THREE.Group();
    row.position.y = ys[i];
    const m = new THREE.Mesh(buildSurfaceGeometry(A), blobMatStatic);
    m.renderOrder = 2;
    row.add(m);
    row.add(makeBallStickGroup(A));
    compareGroup.add(row);
    compareLabels.push(addLabel('<b>' + caps[i] + '</b>', new THREE.Vector3(0, ys[i] - 2.8, 0), { fontSize: '19px' }));
    const nuTxt = ts[i] === 0 ? 'Nu:<sup>−</sup>' : (ts[i] === 1 ? 'Nu' : 'Nu<sup>δ−</sup>');
    const xTxt = ts[i] === 1 ? 'X:<sup>−</sup>' : (ts[i] === 0 ? 'X' : 'X<sup>δ−</sup>');
    compareLabels.push(addLabel(nuTxt, new THREE.Vector3(A.NU.x, ys[i] + 2.2, 0), { fontSize: '15px', color: MAG, bold: true }));
    compareLabels.push(addLabel(xTxt, new THREE.Vector3(A.X.x, ys[i] + 2.2, 0), { fontSize: '15px', color: MAG, bold: true }));
  }
  compareLabels.forEach(l => { l.div.style.visibility = 'hidden'; });
}

/* ── 2D reaction scheme (SVG) ───────────────────────────────────────────── */
function ln(x1, y1, x2, y2, col, w, extra) {
  return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col || '#111'}" stroke-width="${w || 1.6}" stroke-linecap="round" ${extra || ''}/>`;
}
function wdg(x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  const px = -dy / L * 2.7, py = dx / L * 2.7;
  return `<polygon points="${x1},${y1} ${x2 + px},${y2 + py} ${x2 - px},${y2 - py}" fill="#111"/>`;
}
function hsh(x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  const px = -dy / L, py = dx / L;
  let s = '';
  for (let i = 1; i <= 5; i++) {
    const f = i / 5.5, cx = x1 + dx * f, cy = y1 + dy * f, w = 0.9 + 2.1 * f;
    s += ln(cx - px * w, cy - py * w, cx + px * w, cy + py * w, '#111', 1.5);
  }
  return s;
}
function txt(x, y, s, col, size, anchor) {
  return `<text x="${x}" y="${y}" fill="${col || '#111'}" font-family="Georgia,serif" font-size="${size || 15}" text-anchor="${anchor || 'start'}">${s}</text>`;
}
function dot(x, y, col) { return `<circle cx="${x}" cy="${y}" r="1.6" fill="${col}"/>`; }
function skel(cx, cy, s, mode) {
  if (mode === 'ts') {
    return hsh(cx - 3, cy - 6, cx - 11, cy - 22) + wdg(cx + 3, cy - 6, cx + 10, cy - 22) +
      ln(cx, cy + 7, cx, cy + 24) + txt(cx, cy + 5, 'C', '#111', 15, 'middle');
  }
  return wdg(cx - 3 * s, cy - 5, cx - 19 * s, cy - 20) +
    hsh(cx + 3 * s, cy - 6, cx + 11 * s, cy - 23) +
    ln(cx - 4 * s, cy + 5, cx - 17 * s, cy + 19) +
    txt(cx, cy + 5, 'C', '#111', 15, 'middle');
}
function arrow(x, y1, y2) {
  return ln(x, y1, x, y2 - 7) + `<polygon points="${x - 4},${y2 - 8} ${x + 4},${y2 - 8} ${x},${y2}" fill="#111"/>`;
}

const R1 = 42, R2 = 152, R3 = 266;
let svg = `<svg viewBox="0 0 250 306" width="100%" style="display:block">`;
svg += `<g id="schemeRow0" style="cursor:pointer">`
  + txt(10, R1 + 5, 'Nu', MAG, 16) + dot(41, R1 - 2, MAG) + dot(41, R1 + 4, MAG)
  + txt(46, R1 - 4, '−', MAG, 13)
  + txt(62, R1 + 5, '+', '#111', 16)
  + skel(120, R1, 1, 'tet')
  + ln(129, R1, 152, R1)
  + txt(156, R1 + 5, 'X', MAG, 16)
  + `</g>`;
svg += arrow(120, R1 + 28, R1 + 64);
const bt = R2 - 42, bb = R2 + 36;
svg += `<g id="schemeRow1" style="cursor:pointer">`
  + ln(13, bt, 6, bt) + ln(6, bt, 6, bb) + ln(6, bb, 13, bb)
  + ln(237, bt, 243, bt) + ln(243, bt, 243, bb) + ln(237, bb, 243, bb)
  + txt(18, R2 - 22, 'δ', MAG, 13) + txt(27, R2 - 27, '−', MAG, 11)
  + txt(16, R2 + 5, 'Nu', MAG, 16)
  + ln(47, R2, 110, R2, MAG, 1.7, 'stroke-dasharray="2,3.4"')
  + skel(122, R2, 1, 'ts')
  + ln(134, R2, 198, R2, MAG, 1.7, 'stroke-dasharray="2,3.4"')
  + txt(203, R2 + 5, 'X', MAG, 16)
  + txt(203, R2 - 22, 'δ', MAG, 13) + txt(212, R2 - 27, '−', MAG, 11)
  + `</g>`;
svg += arrow(120, R2 + 46, R2 + 82);
svg += `<g id="schemeRow2" style="cursor:pointer">`
  + txt(14, R3 + 5, 'Nu', MAG, 16)
  + ln(45, R3, 69, R3)
  + skel(78, R3, -1, 'tet')
  + txt(140, R3 + 5, '+', '#111', 16)
  + txt(166, R3 + 5, 'X', MAG, 16) + dot(184, R3 - 2, MAG) + dot(184, R3 + 4, MAG)
  + txt(189, R3 - 4, '−', MAG, 13)
  + `</g>`;
svg += `</svg>`;
document.getElementById('schemeBox').innerHTML = svg;
const rowEls = [0, 1, 2].map(i => document.getElementById('schemeRow' + i));
rowEls.forEach((el, i) => el.addEventListener('click', () => {
  if (compareOn) setCompare(false);
  stopPlay(); tweenTo(i * 0.5, 700);
}));

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const slider = document.getElementById('reactionProgress');
const progVal = document.getElementById('progVal');
const btnMap = document.getElementById('modeMap');
const btnBall = document.getElementById('modeBall');
const btnBoth = document.getElementById('modeBoth');
const btnCompare = document.getElementById('modeCompare');
const btnPlay = document.getElementById('btnPlay');

let dirty = true, mode = 'both', compareOn = false, lastSurfT = -9;

function setMode(m) {
  mode = m;
  btnMap.classList.toggle('active', m === 'map');
  btnBall.classList.toggle('active', m === 'ball');
  btnBoth.classList.toggle('active', m === 'both');
  showBS = (m !== 'map');
  blobMesh.visible = (m !== 'ball');
  blobMat.opacity = (m === 'map') ? 0.95 : 0.60;
  blobMat.depthWrite = (m === 'map');
  blobMat.needsUpdate = true;
  dirty = true;
}
btnMap.addEventListener('click', () => { if (compareOn) setCompare(false); setMode('map'); });
btnBall.addEventListener('click', () => { if (compareOn) setCompare(false); setMode('ball'); });
btnBoth.addEventListener('click', () => { if (compareOn) setCompare(false); setMode('both'); });
btnCompare.addEventListener('click', () => setCompare(!compareOn));

function setCompare(on) {
  compareOn = on;
  btnCompare.classList.toggle('active', on);
  if (on) {
    stopPlay(); tween = null;
    if (!compareGroup) buildCompare();
    scene.remove(blobMesh); scene.remove(bsGroup);
    scene.add(compareGroup);
    mainLabels.forEach(l => { l.div.style.visibility = 'hidden'; });
    compareLabels.forEach(l => { l.div.style.visibility = 'visible'; });
    slider.disabled = true; btnPlay.disabled = true;
    progVal.textContent = 'Comparing reactants · transition state · products';
    rowEls.forEach(el => el.setAttribute('opacity', '1'));
    setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 4, heightFraction: 0.94 });
  } else {
    if (compareGroup) scene.remove(compareGroup);
    scene.add(blobMesh); scene.add(bsGroup);
    compareLabels.forEach(l => { l.div.style.visibility = 'hidden'; });
    mainLabels.forEach(l => { l.div.style.visibility = 'visible'; });
    slider.disabled = false; btnPlay.disabled = false;
    setMode(mode === 'ball' ? 'ball' : mode);
    lastSurfT = -9; dirty = true;
    setProgress(progT);
    setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 10, heightFraction: 0.88 });
  }
}

function phaseName(t) {
  if (t < 0.08) return 'Reactants — Nu:⁻ free, C–X intact';
  if (t < 0.42) return 'Backside approach — C–X stretching';
  if (t <= 0.58) return 'Planar transition state — [Nu···C···X]‡';
  if (t < 0.92) return 'Inversion — new C–Nu bond forming';
  return 'Products — inverted, X:⁻ free';
}

function setProgress(v, fromSlider) {
  progT = Math.min(1, Math.max(0, v));
  if (!fromSlider) slider.value = progT.toFixed(2);
  if (!compareOn) progVal.textContent = 't = ' + progT.toFixed(2) + ' · ' + phaseName(progT);
  const active = progT < 0.25 ? 0 : (progT > 0.75 ? 2 : 1);
  if (!compareOn) rowEls.forEach((el, i) => el.setAttribute('opacity', i === active ? '1' : '0.22'));
  dirty = true;
}
slider.addEventListener('input', () => { stopPlay(); setProgress(parseFloat(slider.value), true); });

/* ── guided steps ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Reactants', t: 0, mode: 'both', n: 'The nucleophile is a separate, deeply red sphere holding all of the negative charge; the alkyl halide is a two-lobed tetrahedral surface, red at the halide end and blue-green around the three hydrogens.' },
  { title: 'Backside approach', t: 0.3, mode: 'both', n: 'Nu moves in along the line directly opposite the C–X bond; the C–X bond stretches and the three hydrogens begin to bend away from the incoming nucleophile.' },
  { title: 'Planar transition state', t: 0.5, mode: 'both', n: 'Halfway, the carbon is trigonal planar with Nu and X both half-bonded at 180°. The map is a symmetric three-lobed surface, red at both ends and green-yellow across the middle — the charge is shared, each end carrying δ−.' },
  { title: 'Inversion completes', t: 0.75, mode: 'ball', n: 'Past the transition state the hydrogens snap through to the far side, the new Nu–C bond shortens and the C–X bond breaks — the carbon\'s configuration has been turned inside out.' },
  { title: 'Products', t: 1, mode: 'both', n: 'The product is again tetrahedral but with the wedge and hash reversed, and the negative charge — the deep-red lobe — now lives entirely on the free leaving group X:⁻.' }
];
let stepI = 0;
const stepTitle = document.getElementById('stepTitle'), stepNarr = document.getElementById('stepNarr');
function goToStep(i) {
  stepI = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepI];
  if (compareOn) setCompare(false);
  stopPlay();
  setMode(s.mode);
  tweenTo(s.t, 900);
  stepTitle.textContent = (stepI + 1) + '. ' + s.title;
  stepNarr.textContent = s.n;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepI + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepI - 1));

/* ── tween + play loop ──────────────────────────────────────────────────── */
let tween = null, playing = false, playPhase = 0, lastT = performance.now();
function tweenTo(target, dur) { tween = { from: progT, to: target, t0: performance.now(), dur: dur || 800 }; }
function stopPlay() { if (playing) { playing = false; btnPlay.textContent = '▶ Play mechanism'; btnPlay.classList.remove('active'); } }
btnPlay.addEventListener('click', () => {
  if (compareOn) setCompare(false);
  if (playing) { stopPlay(); return; }
  playing = true; tween = null; playPhase = progT;
  btnPlay.textContent = '❚❚ Pause';
  btnPlay.classList.add('active');
});

function ease(p) { return p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2; }

function snTick(now) {
  requestAnimationFrame(snTick);
  const dt = Math.min(64, now - lastT); lastT = now;
  if (!compareOn) {
    if (playing) {
      playPhase += dt / 2800;
      if (playPhase >= 2) playPhase -= 2;
      const p = playPhase < 1 ? playPhase : 2 - playPhase;
      setProgress(ease(p));
    } else if (tween) {
      const p = Math.min(1, (now - tween.t0) / tween.dur);
      setProgress(tween.from + (tween.to - tween.from) * ease(p));
      if (p >= 1) tween = null;
    }
    if (dirty) {
      dirty = false;
      const A = atomState(progT);
      updateBallStick(A);
      if (blobMesh.visible && Math.abs(progT - lastSurfT) > 0.004) {
        lastSurfT = progT;
        const g = buildSurfaceGeometry(A);
        const old = blobMesh.geometry;
        blobMesh.geometry = g;
        old?.dispose?.();
      }
      updateLabels(A);
    }
  }
}
requestAnimationFrame(snTick);

setMode('both');
setProgress(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

